def min_steps_maze(grid):
    rows = len(grid)
    cols = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting point 'S' and end point 'E'
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            if grid[r][c] == 'E':
                end = (r, c)

    # Set up the queue for BFS
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited = set()
    visited.add(start)

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1

def is_match(str_a: str, str_b: str) -> bool:
    """
    Determines if the input string matches the pattern.
    """
    # Initialize a 2D DP array. dp[i][j] means whether s[0..i) matches p[0..j)
    dp = [[False] * (len(str_b) + 1) for _ in range(len(str_a) + 1)]

    # Base case: empty string matches empty pattern.
    dp[0][0] = True

    # Deals with patterns with '*' at the beginning like a*, a*b*, a*b*c*
    for j in range(1, len(str_b) + 1):
        if str_b[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(str_a) + 1):
        for j in range(1, len(str_b) + 1):
            if str_b[j - 1] == '.' or str_b[j - 1] == str_a[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif str_b[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if str_b[j - 2] == '.' or str_b[j - 2] == str_a[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[len(str_a)][len(str_b)]

import heapq

def dijkstra_algorithm(graph, start, end):
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted graph.

    :param graph: A dictionary representing a weighted graph.
    :param start: A string representing the starting node.
    :param end: A string representing the target node.
    :return: A tuple containing a list of nodes representing the shortest path and the total travel time.
    """
    # Min-heap priority queue
    pq = [(0, start, [])]
    visited = set()
    while pq:
        (cost, node, path) = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        path = path + [node]

        if node == end:
            return (path, cost)

        for neighbor, weight in graph.get(node, {}).items():
            if neighbor not in visited:
                heapq.heappush(pq, (cost + weight, neighbor, path))

    return ([], 0)

