def shortest_path(graph, start, end):
    """
    Returns the shortest path from the start intersection to the end intersection
    using Breadth-First Search.
    """
    if start not in graph or end not in graph:
        return []

    queue = deque([[start]])
    visited = set([start])

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == end:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])

    return []

def valid_path(edges, source, destination):
    """
    Determines if there is a valid path from source to destination in a directed graph.
    """
    from collections import defaultdict, deque

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # BFS to check for path from source to destination
    to_visit = deque([source])
    visited = set()

    while to_visit:
        current = to_visit.popleft()
        if current == destination:
            return True
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    to_visit.append(neighbor)

    return False

