def is_match(s: str, p: str) -> bool:
    """
    Returns whether the input string matches the given pattern.
    The pattern supports '.' which matches any single character, 
    and '*' which matches zero or more of the preceding element.
    """
    # Initialize the DP table
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc should match empty string
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[m][n]

import math

def find_roots(a: float, b: float, c: float) -> dict[str, float]:
    """
    Given the coefficients of a quadratic polynomial, find its real roots.

    Args:
    a (float): Coefficient of x^2
    b (float): Coefficient of x
    c (float): Constant term

    Returns:
    dict: A dictionary containing the real roots with keys 'root1' and 'root2' if there are two distinct real roots,
          'root' if there is one real root, or an empty dictionary if there are no real roots.

    Raises:
    ValueError: If the coefficient 'a' is zero.
    """
    if a == 0:
        raise ValueError("Coefficient 'a' cannot be zero")

    discriminant = b**2 - 4*a*c

    if discriminant > 0:
        root1 = (-b - math.sqrt(discriminant)) / (2 * a)
        root2 = (-b + math.sqrt(discriminant)) / (2 * a)
        return {'root1': min(root1, root2), 'root2': max(root1, root2)}
    elif discriminant == 0:
        root = -b / (2 * a)
        return {'root': root}
    else:
        return {}

def has_path(n, edges, start, end):
    """
    Determine if there exists a path between two nodes using Depth-First Search (DFS) algorithm.

    :param n: An integer representing the number of nodes.
    :param edges: A list of tuples (u, v), where 'u' is the starting node, and 'v' is the ending node of a directed edge.
    :param start: The starting node from which to search (integer).
    :param end: The ending node that we want to reach (integer).
    :return: A boolean value, True if there is a path from `start` to `end`, False otherwise.
    """

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)

    stack = [start]
    visited = set()

    while stack:
        node = stack.pop()
        if node == end:
            return True
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

    return False

