def dfs_traversal(graph, start):
    stack = [start]
    visited = set()
    traversal_order = []

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            # Add adjacent nodes to stack (in reverse order to maintain correct traversal)
            for neighbor in reversed(graph[node]):
                if neighbor not in visited:
                    stack.append(neighbor)

    return traversal_order

def is_match(s: str, p: str) -> bool:
    """
    Returns True if input string s matches the pattern p following the rules of
    regular expression matching with '.' and '*'.
    """
    # Create a DP table to store the results
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Base case: empty string matches empty pattern
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc.
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                # Match empty sequence or match preceding element
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (p[j - 2] == s[i - 1] or p[j - 2] == '.'))

    return dp[len(s)][len(p)]

