def isMatch(text: str, pattern: str) -> bool:
    # Create a DP table with dimensions (len(text) + 1) x (len(pattern) + 1)
    dp = [[False] * (len(pattern) + 1) for _ in range(len(text) + 1)]
    dp[0][0] = True  # Both text and pattern are empty

    # Handle patterns like a*, a*b*, a*b*c* which can match with an empty text
    for j in range(2, len(pattern) + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    for i in range(1, len(text) + 1):
        for j in range(1, len(pattern) + 1):
            if pattern[j-1] == text[i-1] or pattern[j-1] == '.':
                dp[i][j] = dp[i-1][j-1]
            elif pattern[j-1] == '*':
                dp[i][j] = dp[i][j-2]  # * means 0 occurrence
                if pattern[j-2] == text[i-1] or pattern[j-2] == '.':
                    dp[i][j] |= dp[i-1][j]  # * means 1 or more occurrence

    return dp[len(text)][len(pattern)]

def transitive_closure(vertices, edges):
    """
    Computes the transitive closure of a directed graph.

    :param vertices: Number of vertices in the graph.
    :param edges: List of pairs (source, target) representing directed edges in the graph.
    :return: A 2D list representing the transitive closure of the graph.
    """
    closure = [[0] * vertices for _ in range(vertices)]

    # Initialize the adjacency matrix representation of the graph
    for i in range(vertices):
        closure[i][i] = 1  # Every vertex is reachable from itself

    for u, v in edges:
        closure[u][v] = 1

    # Use the Floyd-Warshall algorithm to compute the transitive closure
    for k in range(vertices):
        for i in range(vertices):
            for j in range(vertices):
                if closure[i][k] and closure[k][j]:
                    closure[i][j] = 1

    return closure

