import heapq

def shortest_path_with_constraints(roads, source, destination, blocked):
    # Create an adjacency list for graph representation
    graph = {}
    for u, v, t in roads:
        if (u, v) in blocked or (v, u) in blocked:
            continue
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Use a priority queue to implement Dijkstra's algorithm
    pq = [(0, source)]  # (distance, node)
    distances = {source: 0}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_distance

        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

